$(".form").find("input, select").on("focus blur change keyup",function(){const label=$(this).prev("label");if($(this).val()){label.addClass("active");}else{label.removeClass("active");}});$(".tab a").on("click",function(e){e.preventDefault();$(this).parent().addClass("active").siblings().removeClass("active");const target=$(this).attr("href");$(".tab-content > div").removeClass("active").hide();$(target).addClass("active").fadeIn(400);});;